/**
 * Registers the service worker of the production build (`/sw.js`, generated by the plugin in
 * `vite.config.ts`). It precaches the app shell, so Mive opens without internet; the data
 * comes from IndexedDB. A new version waits until every tab of the old one is closed.
 */
export function registerServiceWorker() {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(error => console.warn('Service worker não registrado', error));
  });
}
